// every_document_we_issue.test.ts — every document type the company issues, rendered through its REAL
// builder and the real renderer with ZZ DEMO data, and checked page by page. Seat: sales_engineer.
//
// 22 Sep 2026. The founder (instructions 568, 569): "not a single pdf should be generated by our team
// unless its as per our template". The static gate (scripts/checks/every_pdf_we_issue_is_on_our_template.mjs)
// passed that day while an audit that RENDERED 37 samples found: the regenerated quotation was a blank
// page titled "Document" (its body was a shape the renderer never reads); Arabic pages without a cover
// printed the English licence line; the IT incident record and the conversation archive had no licence
// line at all; the archive's Arabic page said "Sept" and "Correspondence archive"; the renderer's navy was
// not the brand table's. None of that is visible to a check that reads source. This one looks at the page.
//
// For every document: it renders (nothing refused), 0 characters dropped, a body (not only furniture),
// the letterhead (issuer name, DET licence 1633275, TDRA permit), the licence line in the document's own
// language, no English interface word on an Arabic page (Latin that is the document's DATA — names,
// emails, codes — is allowed), and the brand navy #0C2330 is what fills the band.
//
// No network, no database: fonts are the committed copies in fixtures/brand. The lockup PNGs are fetched
// only when this is run by hand with SUPABASE_URL and net granted, and the PDFs are written only when
// QD_PDF_OUT is set and writable:
//   QD_PDF_OUT=<dir> SUPABASE_URL=https://<ref>.supabase.co deno test -A supabase/functions/pdf_native/every_document_we_issue.test.ts
import { assert } from 'jsr:@std/assert@1';
import { renderPdf } from './render.ts';
import { pdfPageContents, pdfTextByRows } from '../_shared/pdf_text_positions.ts';
import { BRAND } from '../_shared/brand.ts';
// The documents (each through its real builder, ZZ DEMO data) live in every_document_we_issue.fixtures.ts, shared with the
// investor pack (scripts/investor_pack/every_template_in_one_pdf.ts, ledger 1547).
import { docs } from './every_document_we_issue.fixtures.ts';

const FONTS = new URL('./fixtures/brand/', import.meta.url);
const granted = (d: Deno.PermissionDescriptor) => Deno.permissions.querySync(d).state === 'granted';
const URL_ = granted({ name: 'env', variable: 'SUPABASE_URL' }) && granted({ name: 'net' }) ? Deno.env.get('SUPABASE_URL') : undefined;
const OUT = granted({ name: 'env', variable: 'QD_PDF_OUT' }) ? Deno.env.get('QD_PDF_OUT') : undefined;
const fetchBytes = async (p: string) => {
  if (/\.ttf$/.test(p)) return await Deno.readFile(new URL(p, FONTS));
  if (!URL_) return null;
  try { const r = await fetch(`${URL_}/storage/v1/object/public/brand/${p}`); return r.ok ? new Uint8Array(await r.arrayBuffer()) : null; } catch { return null; }
};

// ── The page checks ─────────────────────────────────────────────────────────────────────────────
const norm = (s: string) => s.normalize('NFKC');
const rev = (s: string) => [...s].reverse().join('');
const has = (text: string, phrase: string) => { const t = norm(text); return t.includes(phrase) || t.includes(rev(phrase)); };
const FURNITURE = /QuotesDone Technologies|1633275|100000665|management@quotesdone|\+1 218 316 6814|^Page \d|صفحة|ةحفص/;
// Latin words any Arabic page may carry: the issuer's proper names and codes, and the renderer's own.
const ALWAYS = new Set(['quotesdone', 'technologies', 'tdra', 'nol', 'aed', 'stripe', 'zz', 'demo', 'qd', 'utc', 'sha', 'pdf', 'www', 'https', 'http', 'com', 'ae', 'management', 'invalid', 'example', 'visa', 'card', 'nos', 'tr',
  // reference-code suffixes (QD-<job>-CMP / -RFQ, <case>-GUIDE) and the courts' domain (dc.gov.ae)
  'cmp', 'rfq', 'guide', 'gov']);
const wordsOf = (v: unknown) => new Set((JSON.stringify(v ?? '').match(/[A-Za-z0-9]{2,}/g) || []).flatMap((w) => w.toLowerCase().match(/[a-z]{2,}/g) || []));
/** A fill whose colour is within half a step of `hex`, in a page's decoded content. */
function fills(content: string, hex: string) {
  const want = [1, 3, 5].map((i) => parseInt(hex.slice(i, i + 2), 16) / 255);
  for (const m of content.matchAll(/([\d.]+)\s+([\d.]+)\s+([\d.]+)\s+rg\b/g)) {
    if ([1, 2, 3].every((k) => Math.abs(Number(m[k]) - want[k - 1]) < 0.002)) return true;
  }
  return false;
}

for (const d of docs) {
  Deno.test(`${d.type} (${d.lang}) is issued on the QuotesDone template`, async () => {
    const r = await renderPdf(d.body, { fetchBytes });
    assert(r.ok, `refused: ${JSON.stringify((r as { body?: unknown }).body)}`);
    if (!r.ok) return;
    if (OUT) await Deno.writeFile(`${OUT}/${d.type}_${d.lang}.pdf`, r.bytes);
    assert(r.meta.glyphs_dropped === 0, `${r.meta.glyphs_dropped} character(s) dropped: ${r.meta.glyphs_dropped_sample}`);
    const text = await pdfTextByRows(r.bytes);
    const lines = text.split('\n').map((s) => s.trim()).filter(Boolean);
    const body = lines.filter((s) => !FURNITURE.test(norm(s)));
    // A BODY: the blank regenerated quotation had a title "Document", one meta line and the footer.
    assert(r.title !== 'Document', 'untitled: the body shape is not one the renderer reads');
    assert(body.length >= 4, `no body — only ${body.length} line(s) besides the letterhead: ${body.join(' | ')}`);
    if (d.needle) assert(text.includes(d.needle), `the document's content "${d.needle}" is not on the page`);
    // THE LETTERHEAD.
    assert(text.includes('QuotesDone Technologies') && text.includes('1633275') && text.includes('100000665'), 'letterhead: issuer, DET licence or TDRA permit missing');
    // THE LICENCE LINE IN THE DOCUMENT'S LANGUAGE.
    if (d.lang === 'ar') {
      assert(has(text, 'رخصة تاجر'), 'the Arabic licence line is missing');
      assert(!/Trader Licen[cs]e|\bDET\b/.test(text), 'an Arabic page prints the English licence line');
      // NO ENGLISH INTERFACE WORD: a Latin word that is not in the document's own data.
      const allowed = new Set([...ALWAYS, ...wordsOf(d.data)]);
      // A data value wrapped across two lines arrives in pieces ('invali' + 'd'): a piece of a data word is data.
      const isData = (w: string) => allowed.has(w) || [...allowed].some((a) => a.length > w.length && a.includes(w));
      const leaks = [...new Set((text.match(/[A-Za-z]{3,}/g) || []).filter((w) => !isData(w.toLowerCase())))];
      assert(leaks.length === 0, `English on the Arabic page: ${leaks.slice(0, 12).join(', ')}`);
    } else {
      assert(text.includes('Trader License No. 1633275'), 'the English licence line is missing');
    }
    // THE BRAND NAVY from the table fills the band, and the old off-table navy is gone.
    const pages = await pdfPageContents(r.bytes);
    assert(fills(pages[0].content, BRAND.navy), `page 1 has no ${BRAND.navy} fill`);
    assert(!pages.some((p) => fills(p.content, '#0A1720')), 'the off-table navy #0A1720 is drawn');
  });
}

Deno.test('every document type is covered', () => {
  const types = new Set(docs.map((d) => d.type.replace(/^recovery_.*/, 'recovery')));
  for (const t of ['quotation', 'comparison_report', 'request_brief', 'regenerated_quotation', 'reveal_invoice', 'reveal_receipt', 'supplier_registration_invoice',
    'supplier_registration_receipt', 'supplier_dues_invoice', 'supplier_dues_receipt', 'terms_certificate_supplier', 'terms_certificate_customer',
    'conversation_archive', 'recovery', 'email_print', 'it_incident', 'internal_report', 'dropbox_backup_profile']) assert(types.has(t), 'missing ' + t);
});
